/-- Deterministic observation, with a zero outcome mark when the outcome does not arrive. -/
def observe {d : ℕ} (w : FullAtom d) : Obs d :=
  ⟨w.X, w.A, w.S, w.R, w.R && w.Y⟩

/-- The two orientations at a pair are opposite. -/
def orientation (θ : Theta n d) (j : Fin (pairCount n d)) (side : Bool) : ℝ :=
  if θ.2 j == side then 1 else -1

/-- Falling factorial `(C-1)_{v-1}` for a positive index `v`. -/
def shiftedFalling (C : ℝ) (v : ℕ) : ℝ :=
  ∏ t ∈ Finset.range (v - 1), (C - 1 - (t : ℝ))
